func (m *Model) key(pressed tea.KeyPressMsg) tea.Cmd {
	key := pressed.String()
	// A notice and a message both live until the next keypress, whatever
	// that key was. Cleared FIRST, so a handler below can set either and
	// have it survive the press that produced it.
	m.notice, m.message = "", ""

	// The y/n line is answered before anything else can be reached: it is up
	// because a write is waiting on it, and `reopen` destroying a close
	// reason behind an unrelated keypress is the whole thing it prevents.
	//
	// `y` alone is yes and EVERY other key is no. A prompt that only two keys
	// dismiss traps a reader who pressed it by accident inside a full-screen
	// program, and the safe answer is the common one.
	if m.ask != nil {
		asked := m.ask
		m.ask = nil
		if key == "y" {
			asked.confirm()
		}
		return nil
	}

	// The help screen replaces the WHOLE frame, so it captures every key.
	// Anything else would act invisibly behind it, and one of those actions
	// broke `esc` outright: `x` opened an Actions modal under the help, and
	// the modal — which captures input — then swallowed the `esc` meant to
	// close the help, so the key did nothing a reader could see and the next
	// `enter` ran a write off a screen that never showed the picker (m3z5y).
	//
	// Capturing here is also what makes the ordering below total: a modal
	// cannot be open under the help, because `?` cannot be pressed inside one.
	// `esc` still goes through escape(), so the ordering has ONE home.
	if m.help {
		switch key {
		case "q", "ctrl+c":
			return tea.Quit
		case "?":
			m.help = false
		case "esc":
			m.escape()
		}
		return nil
	}

	// A modal captures input while it is open, which is what keeps `esc`
	if measured.truncate {
		title = Ellipsis(title, measured.width-Cols(lead)-1)
	}
	// No trailing space when nothing is left to print, so a row that is all
	// gutter still ends where its last column does.
	if title == "" {
		fmt.Fprintln(out, lead)
	} else {
		fmt.Fprintf(out, "%s %s\n", lead, title)
	}
	if row.Note != "" {
		fmt.Fprintf(out, "    %s\n", row.Note)
	}
}

// StatusMark is the one-glyph status vocabulary shared by issue rows, issue
// pages, related issues and memory rows, so those surfaces cannot drift.
// Nothing parses these: every scripted consumer reads --json.
func StatusMark(status model.Status, tombstoned bool) string {
	if tombstoned {
		return "⊘"
	}
	switch status {
	case model.StatusClosed:
		return "●"
	case model.StatusInProgress:
		return "◐"
	}
	return "○"
}

